const root = $('Root folder ready').first().json;
const photos = $('Photos subfolder ready').first().json;
const sheet = $('Sheet ready').first().json;
const data = $getWorkflowStaticData('global');
data.rootFolderId = root.id;
data.photosFolderId = photos.id;
data.spreadsheetId = sheet.spreadsheetId || (sheet.spreadsheet || {}).spreadsheetId || sheet.id;
if (!data.spreadsheetId) throw new Error('Could not resolve spreadsheetId from: ' + JSON.stringify(sheet).slice(0, 300));
return [{ json: { rootFolderId: data.rootFolderId, photosFolderId: data.photosFolderId, spreadsheetId: data.spreadsheetId, sheetJustCreated: !!sheet.wasCreated } }];

const f = $input.first().json;
const rawSlug = (f['Business slug'] || '').toString().trim().toLowerCase();
const slug = rawSlug.replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '');
if (!slug) throw new Error('Business slug is empty or invalid');
let website = (f['Website URL'] || '').toString().trim();
if (!/^https?:\/\//i.test(website)) website = 'https://' + website;
if (!/^https?:\/\/[^\s\/]+\.[^\s\/]{2,}/i.test(website)) throw new Error('Invalid website URL: ' + website);
const businessName = (f['Business name'] || '').toString().trim();
const chatId = (f['Telegram chat ID'] || '').toString().trim();
const language = (f['Content language'] || 'English').toString().trim();
const notes = (f['Notes on tone / do-not-say'] || '').toString().trim();
return [{ json: { slug, businessName, website, chatId, language, notes } }];

const ctx = $('Prepare context').first().json;
const origin = ctx.website.split('/').slice(0, 3).join('/');
const norm = (u) => (u.split('#')[0].split('?')[0].replace(/\/+$/, '')) || origin;
const excluded = (u) => {
  const path = u.slice(origin.length).toLowerCase();
  return /\.(pdf|jpe?g|png|gif|webp|svg|ico|css|js|mjs|json|xml|txt|zip|mp4|webm|woff2?|ttf|otf|eot|map|webmanifest)(\?|$)/.test(path)
    || /^\/(assets|static|_next|fonts|img|images|media|api)\//.test(path)
    || /(privacy|terms|cookie|legal)/.test(path);
};

// Ecommerce noise, across the 5 languages this product's onboarding form
// offers (English, Español, Français, Deutsch, Italiano) — individual
// products and category listings are never good identity-page candidates,
// in any language, so they're excluded outright rather than used as a
// fallback.
const CATALOG_TERMS = ['products?','product','p','categor(y|ies)','category','c','shop','store','blog','news',
  'productos?','producto','categorias?','categoria','tienda','coleccion(es)?',
  'produits?','categories?','boutique','magasin',
  'produkte?','kategorien?','geschaeft',
  'prodott[oi]','categorie','negozio'];
const CATALOG_RE = new RegExp('^/(' + CATALOG_TERMS.join('|') + ')(/|$)', 'i');
const isCatalog = (u) => CATALOG_RE.test(u.slice(origin.length).toLowerCase());

// Identity pages worth showing first — same 5 languages. A plain lookup
// list instead of clever heuristics: cheap, predictable, easy to extend.
const IDENTITY_TERMS = ['about(-us)?','who-we-are','our-team','team','company','services?','specialt(y|ies)','solutions','contact(-us)?','case-studies','portfolio','work',
  'sobre-nosotros','quienes-somos','nosotros','nuestra-empresa','empresa','equipo','servicios','contacto','casos-de-exito',
  'a-propos','qui-sommes-nous','notre-equipe','entreprise','contact',
  'ueber-uns','uber-uns','unternehmen','leistungen','kontakt',
  'chi-siamo','la-nostra-storia','squadra','servizi','contatt[oi]','azienda'];
const IDENTITY_RE = new RegExp('/(' + IDENTITY_TERMS.join('|') + ')(/|$)', 'i');

const depth = (u) => u.slice(origin.length).split('/').filter(Boolean).length;

// Hard budget: at most 500 KB of XML and 2,000 <loc> entries — a 40 MB
// sitemap with 15,000 products must never be able to spike the container.
// Sitemap *indexes* (a list of other sitemap files, not pages — common on
// ecommerce platforms) are not expanded: no extra fetch, no extra depth.
// Their <loc> entries are themselves .xml files, so they're filtered out
// below like any other asset, and the flow correctly falls through to the
// homepage-HTML pass instead.
const sitemapXml = ($input.first().json.data || '').toString().slice(0, 500000);
const locs = [];
for (const m of sitemapXml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)) {
  locs.push(m[1].trim());
  if (locs.length >= 2000) break;
}
const same = [...new Set(locs.map(norm))]
  .filter(u => u.toLowerCase().startsWith(origin.toLowerCase()) && !excluded(u));

const urls = new Set([norm(ctx.website)]);

// Layer 1: identity pages first — guaranteed a slot
for (const u of same) { if (urls.size >= 6) break; if (IDENTITY_RE.test(u.slice(origin.length))) urls.add(u); }

// Layer 2: the rest, no catalog paths, no depth > 2, shortest first
const rest = same.filter(u => !urls.has(u) && !isCatalog(u) && depth(u) <= 2).sort((a, b) => a.length - b.length);
for (const u of rest) { if (urls.size >= 6) break; urls.add(u); }

// Fallback: links from the homepage HTML (no usable sitemap, or the whole
// sitemap was an index/catalog and layers 1-2 found nothing) — same
// identity-first, no-catalog rules, so an ecommerce homepage doesn't just
// fill up with product links.
if (urls.size < 3) {
  const html = $('Download homepage').first().json.data || '';
  const re = /href\s*=\s*["']([^"'#\s]+)["']/gi;
  const candidates = new Set();
  let m;
  while ((m = re.exec(html)) !== null) {
    const href = m[1].trim();
    if (/^(mailto:|tel:|javascript:|data:)/i.test(href)) continue;
    let abs;
    if (/^https?:\/\//i.test(href)) { if (!href.toLowerCase().startsWith(origin.toLowerCase())) continue; abs = href; }
    else if (href.startsWith('//')) continue;
    else if (href.startsWith('/')) abs = origin + href;
    else continue;
    abs = norm(abs);
    if (excluded(abs) || isCatalog(abs) || depth(abs) > 2) continue;
    candidates.add(abs);
  }
  const list = [...candidates];
  for (const u of list) { if (urls.size >= 6) break; if (IDENTITY_RE.test(u.slice(origin.length))) urls.add(u); }
  for (const u of list.sort((a, b) => a.length - b.length)) { if (urls.size >= 6) break; urls.add(u); }
}
return [...urls].map(url => ({ json: { url }, pairedItem: { item: 0 } }));

const pages = $input.all();
const clean = (html) => html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
let total = 0;
const blocks = [];
for (const p of pages) {
  if (!p.json || p.json.error || typeof p.json.data !== 'string') continue;
  const text = clean(p.json.data).slice(0, 8000);
  if (text.length < 100) continue;
  blocks.push(text);
  total += text.length;
  if (total > 30000) break;
}
if (blocks.length === 0) throw new Error('Could not extract any text from the website');
return [{ json: { websiteText: blocks.join('\n\n---\n\n') } }];

// TODO: once you have Google Business Profile API access, replace this mock
// with real calls (Business Information API + mybusiness v4: services, photos,
// reviews, Q&A). Nothing else in this flow needs to change — just fill this shape.
return [{ json: { gbp: { mock: true, categories: [], services: [], photos: [], reviews: [], qna: [] } } }];

const ctx = $('Prepare context').first().json;
const websiteText = $('Compile website text').first().json.websiteText;
const gbp = $('GBP seed (mock)').first().json.gbp;
const existing = $input.all();
const identityExists = existing.length > 0 && !!(existing[0].json && existing[0].json.slug);
const chatInput = [
  'Business: ' + ctx.businessName + ' (slug: ' + ctx.slug + ')',
  'Website: ' + ctx.website,
  'Content language: ' + ctx.language,
  ctx.notes ? 'Operator notes:\n' + ctx.notes : '',
  '\n=== WEBSITE TEXT ===\n' + websiteText,
  '\n=== GOOGLE BUSINESS PROFILE DATA ===\n' + JSON.stringify(gbp, null, 2)
].filter(Boolean).join('\n');
return [{ json: { chatInput, identityExists } }];

const out = $('AI: Synthesize knowledge base').first().json.output;
const slug = $('Prepare context').first().json.slug;
const services = out.services || [];
return services.map(s => ({ json: {
  slug, service_name: s.name, description: s.description || '',
  keywords: (s.keywords || []).join(', '), last_piece_date: ''
} }));

const client = $json;
const mine = (rows) => rows.map(i => i.json).filter(r => r.slug === client.slug);
const services = mine($('Read services').all());
const photos = mine($('Read photos').all());
const promos = mine($('Read promos').all());
const history = mine($('Read history').all());
const identityRows = mine($('Read identity').all());
const identity = identityRows[0] || {};
// Newest first and capped: learnings go into the prompt as hard constraints,
// and an unbounded list would eventually crowd out the actual brief.
const seenInsight = new Set();
const learnings = mine($('Read learnings').all()).filter(l => l.insight)
  .filter(l => { const k = String(l.insight).trim(); if (seenInsight.has(k)) return false; seenInsight.add(k); return true; })
  .sort((a, b) => String(b.date || '').localeCompare(String(a.date || ''))).slice(0, 12);

const isTrue = (v) => v === true || String(v).trim().toLowerCase() === 'true';
const now = Date.now();
const weeksSince = (serviceName) => {
  const pieces = history.filter(h => h.objective === serviceName);
  if (!pieces.length) return Infinity;
  const last = Math.max(...pieces.map(h => Date.parse(h.date) || 0));
  return (now - last) / (7 * 24 * 3600 * 1000);
};
const promoUsed = (title) => history.some(h => h.objective === title);

let plan = null;
const freePromo = promos.find(p => !isTrue(p.used) && !promoUsed(p.title));
const freePhoto = photos.find(p => !isTrue(p.used));
if (freePromo) {
  plan = { pieceType: 'promo_post', objective: freePromo.title, reason: 'unused active promo', data: freePromo };
} else if (freePhoto) {
  plan = { pieceType: 'photo', objective: freePhoto.label, reason: 'photo not yet used', data: freePhoto };
} else if (services.length) {
  const ranked = services.map(s => ({ s, weeks: weeksSince(s.service_name) })).sort((a, b) => b.weeks - a.weeks);
  const worst = ranked[0];
  if (worst.weeks >= 4) {
    plan = { pieceType: 'update_post', objective: worst.s.service_name,
      reason: worst.weeks === Infinity ? 'service has no content yet' : 'no content for ' + Math.floor(worst.weeks) + ' weeks',
      data: worst.s };
  } else {
    const empty = services.find(s => !s.description);
    if (empty) plan = { pieceType: 'service_update', objective: empty.service_name, reason: 'reoptimize: service has no description', data: empty };
    else plan = { pieceType: 'update_post', objective: worst.s.service_name, reason: 'maintenance: most-neglected service', data: worst.s };
  }
}
if (!plan) return { json: { skip: true, slug: client.slug } };

const chatInput = [
  'CLIENT: ' + client.slug,
  'PIECE TO WRITE: ' + plan.pieceType + ' | OBJECTIVE: ' + plan.objective,
  'WHY THIS WAS CHOSEN: ' + plan.reason,
  'OBJECTIVE DATA: ' + JSON.stringify(plan.data),
  '',
  '=== BUSINESS IDENTITY ===',
  'Tone: ' + (identity.tone || ''),
  'Differentiators: ' + (identity.differentiators || ''),
  'Target audience: ' + (identity.target_audience || ''),
  'Never say: ' + (identity.forbidden || ''),
  'Content language: ' + (client.language || 'English'),
  ...(learnings.length ? ['', '=== LESSONS FROM PIECES THIS CLIENT REJECTED ===', 'Treat each as a hard constraint.', ...learnings.map(l => '- ' + l.insight)] : [])
].join('\n');

return { json: { skip: false, slug: client.slug, chatId: client.telegram_chat_id, publishMode: client.publish_mode || 'approval', plan, chatInput } };

const plan = $('Plan piece').item.json;
const out = $json.output;
if (!out || !out.text) throw new Error('Writer did not return text for ' + plan.slug);
const today = new Date().toISOString().slice(0, 10);
const pieceId = plan.slug + '__' + today + '__' + plan.plan.pieceType;
return { json: {
  pieceId, slug: plan.slug, date: today, pieceType: plan.plan.pieceType, objective: plan.plan.objective,
  reason: plan.plan.reason, title: out.title, text: out.text, chatId: plan.chatId, publishMode: plan.publishMode
} };

const j = $('Prepare history row').item.json;
if (!j.chatId) throw new Error('No Telegram chat ID for client ' + j.slug + ' — check its telegram_chat_id in the Clients sheet');
return { json: { pieceId: j.pieceId, slug: j.slug, chatId: j.chatId, title: j.title, text: j.text, pieceType: j.pieceType, autopilot: String(j.publishMode).trim().toLowerCase() === 'autopilot' } };

