const cq = $input.first().json.callback_query;
if (!cq || !cq.data) throw new Error('No callback_query in trigger payload');
const [action, pieceId] = cq.data.split(':');
return [{ json: { action, pieceId, queryId: cq.id, chatId: cq.message.chat.id } }];

const cb = $('Parse callback').first().json;
const status = cb.action === 'appr' ? 'approved_pending_gbp' : 'vetoed';
const spreadsheetId = $('Find database (approval)').first().json.id;
return [{ json: { pieceId: cb.pieceId, status, chatId: cb.chatId, spreadsheetId } }];

const piece = $('Read piece').first().json;
const existing = $('Read learnings (approval)').all().map(i => i.json).filter(l => l.insight);
const chatInput = [
  'A human rejected the following piece. No reason was given.',
  '',
  'PIECE TYPE: ' + (piece.piece_type || ''),
  'OBJECTIVE: ' + (piece.objective || ''),
  'TITLE: ' + (piece.title || ''),
  'TEXT: ' + (piece.text || ''),
  '',
  '=== RULES ALREADY LEARNED FOR THIS CLIENT ===',
  existing.length ? existing.map(l => '- ' + l.insight).join('\n') : '(none yet)'
].join('\n');
return [{ json: { chatInput, slug: piece.slug, spreadsheetId: $('Find database (approval)').first().json.id } }];

const q = $('Dashboard webhook').first().json.query || {};
const slug = (q.slug || '').toString().replace(/[^a-z0-9-]/g, '');
return [{ json: { action: q.action || '', slug } }];

const client = $input.first().json;
const act = $('Apply action (if any)').first().json.action;
let active = client.active, mode = client.publish_mode;
const isTrue = (v) => v === true || String(v).trim().toLowerCase() === 'true';
if (act === 'pause') active = 'false';
if (act === 'resume') active = 'true';
if (act === 'toggle_mode') mode = String(mode).trim().toLowerCase() === 'autopilot' ? 'approval' : 'autopilot';
return [{ json: { slug: client.slug, active: String(active), publish_mode: mode } }];

const clients = $('Read all clients (dashboard)').all().map(i => i.json).filter(c => c.slug);
const history = $('Read all history (dashboard)').all().map(i => i.json).filter(h => h.slug);
const esc = (s) => (s || '').toString().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const isTrue = (v) => v === true || String(v).trim().toLowerCase() === 'true';
const base = (params) => '?' + params;
// Derive the photo form's URL from this request's own host so the button
// keeps working on whatever instance the template is imported into.
const h = $('Dashboard webhook').first().json.headers || {};
const host = h['x-forwarded-host'] || h.host || '';
const proto = h['x-forwarded-proto'] || 'https';
const photoUrl = (slug) => host ? (proto + '://' + host + '/form/gbp-scaler-photo?slug=' + encodeURIComponent(slug)) : '';

const cards = clients.map(c => {
  const active = isTrue(c.active);
  const mode = c.publish_mode || 'approval';
  const pieces = history.filter(h => h.slug === c.slug).sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const counts = {};
  for (const p of pieces) counts[p.status] = (counts[p.status] || 0) + 1;
  const summary = Object.entries(counts).map(([k, v]) => v + ' ' + k).join(' &middot; ') || 'no pieces yet';
  const rows = pieces.slice(0, 8).map(p => '<li><b>' + esc(p.title) + '</b> <small style="color:#6B7280">' + esc((p.date || '').slice(0, 10)) + ' &middot; ' + esc(p.status) + '</small></li>').join('');
  return '<div style="border:1px solid #111827;border-radius:6px;box-shadow:2px 2px 0 #111827;background:#F8F9FA;padding:1rem 1.2rem;margin:1rem 0">'
    + '<div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:0.5rem">'
    + '<strong style="font-size:1.1rem">' + esc(c.business_name || c.slug) + '</strong>'
    + '<span style="font-family:ui-monospace,monospace;font-size:0.85rem">' + (active ? '<span style="color:#008A3E">&#9679; ACTIVE</span>' : '<span style="color:#DC2626">&#9679; PAUSED</span>') + ' &middot; ' + esc(mode) + '</span></div>'
    + '<p style="margin:0.4rem 0;color:#4B5563"><b>Pieces:</b> ' + summary + '</p>'
    + (rows ? '<details><summary style="cursor:pointer">History (latest ' + Math.min(pieces.length, 8) + ')</summary><ul>' + rows + '</ul></details>' : '')
    + '<p style="margin:0.6rem 0 0">'
    + '<a href="' + base('slug=' + c.slug + '&action=' + (active ? 'pause' : 'resume')) + '" style="font-family:ui-monospace,monospace;border:1px solid #111827;border-radius:4px;padding:0.2rem 0.6rem;text-decoration:none;color:#0A0A0A;background:' + (active ? '#FEFCE8' : '#E6F4EA') + '">' + (active ? '[ Pause ]' : '[ Resume ]') + '</a> '
    + '<a href="' + base('slug=' + c.slug + '&action=toggle_mode') + '" style="font-family:ui-monospace,monospace;border:1px solid #111827;border-radius:4px;padding:0.2rem 0.6rem;text-decoration:none;color:#0A0A0A;background:#F1F3F5">[ Switch to ' + (String(mode).toLowerCase() === 'autopilot' ? 'approval' : 'autopilot') + ' ]</a> '
    + (photoUrl(c.slug) ? '<a href="' + photoUrl(c.slug) + '" style="font-family:ui-monospace,monospace;border:1px solid #111827;border-radius:4px;padding:0.2rem 0.6rem;text-decoration:none;color:#0A0A0A;background:#EFF6FF">[ Upload photo ]</a>' : '')
    + '</p>'
    + '</div>';
}).join('');

const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Google Business Scaler — Dashboard</title></head>'
  + '<body style="font-family:system-ui,sans-serif;max-width:50rem;margin:1.5rem auto;padding:0 1rem;color:#0A0A0A;background:#FFFFFF">'
  + '<p style="font-family:ui-monospace,monospace;color:#008A3E;font-weight:700;letter-spacing:0.05em">[ GOOGLE BUSINESS SCALER &middot; DASHBOARD ]</p>'
  + (cards || '<p>No clients yet. Add one via the onboarding form.</p>')
  + '<p style="color:#6B7280;font-size:0.85rem;margin-top:2rem">Changes apply immediately to the Clients sheet.</p>'
  + '</body></html>';
return [{ json: { html } }];

const item = $('Form: Upload photo').first();
const f = item.json;
const slug = (f.slug || '').toString().trim().toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '');
if (!slug) throw new Error('Business slug is empty or invalid');
const label = (f.label || '').toString().trim();
if (!label) throw new Error('Please describe what the photo shows');
if (!item.binary || !item.binary.Photo) throw new Error('No photo file was received');
const folder = $('Find Photos folder (photo)').first().json;
if (!folder || !folder.id) throw new Error('Photos folder not found in Drive — run Setup once before uploading photos');
return [{ json: { slug, label, service: (f.service || '').toString().trim(), folderId: folder.id }, binary: item.binary }];
